from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing elements in parallel on a thread pool.

    The output preserves the order of the input. An empty input returns an empty list.
    """
    if not xs:
        return []
    with ThreadPoolExecutor() as pool:
        return list(pool.map(square, xs))


def test_squares_basic() -> None:
    assert squares([1, 2, 3]) == [1, 4, 9]


def test_squares_preserves_order() -> None:
    xs = [5, -3, 0, 2, -1]
    assert squares(xs) == [square(x) for x in xs]


def test_squares_negatives() -> None:
    assert squares([-4, -2]) == [16, 4]


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_large_input_matches_serial() -> None:
    xs = list(range(-1000, 1000))
    assert squares(xs) == [x * x for x in xs]


def test_squares_does_not_mutate_input() -> None:
    xs = [3, 1, 2]
    original = list(xs)
    squares(xs)
    assert xs == original


@pytest.mark.parametrize("x", [0, 1, -1, 12345])
def test_squares_single_element(x: int) -> None:
    assert squares([x]) == [x * x]
